import sys
def main():
    data=sys.stdin.read().split()
    n=int(data[0])
    yOf=[0]*n; inv=[0]*n
    for i in range(n):
        x=int(data[1+2*i])-1; y=int(data[2+2*i])-1
        yOf[x]=y; inv[y]=x
    NE=[0]*n; SW=[0]*n
    for i in range(n):
        m1=0; m2=0
        for j in range(n):
            if j>i and yOf[j]>yOf[i]: m1|=1<<j
            if j<i and yOf[j]<yOf[i]: m2|=1<<j
        NE[i]=m1; SW[i]=m2
    pref=[0]*(n+1)
    for v in range(n):
        pref[v+1]=pref[v]|(1<<inv[v])
    def good(lo,hi,ylo,yhi):
        XR=((1<<hi)-1) & ~((1<<(lo+1))-1)
        YR=pref[yhi] & ~pref[ylo+1]
        R=XR&YR
        m=R
        while m:
            low=m&-m; i=low.bit_length()-1; m^=low
            if (NE[i]&R)==0 and (SW[i]&R)==0:
                return False
        return True
    MOD=998244353
    dp=[0]*n
    for c in range(n):
        yc=yOf[c]
        v=1 if good(-1,c,yc,n) else 0
        for a in range(c):
            if yOf[a]>yc and dp[a]:
                if good(a,c,yc,yOf[a]):
                    v+=dp[a]
        dp[c]=v%MOD
    chains=0
    for c in range(n):
        if dp[c] and good(c,n,-1,yOf[c]):
            chains+=dp[c]
    chains%=MOD
    U=[p for p in range(n) if NE[p]==0 and SW[p]==0]
    extra=1
    if U:
        Us=set(U)
        full=True
        for p in range(n):
            if p in Us: continue
            ok=True
            for u in U:
                if (NE[u]>>p)&1 or (SW[u]>>p)&1:
                    ok=False;break
            if not ok:
                full=False;break
        if full: extra=0
    print((chains+extra)%MOD)
