import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    M = max(a) + 1
    # Omega(x): number of prime factors with multiplicity
    omega = [0] * M
    spf = list(range(M))
    i = 2
    while i * i < M:
        if spf[i] == i:
            for j in range(i * i, M, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    for x in range(2, M):
        omega[x] = omega[x // spf[x]] + 1
    g = 0
    for v in a:
        g ^= omega[v]
    print("Anna" if g else "Bruno")

