from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        pairs_by_b = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            pairs_by_b[b].append((a, idx))
        gain = [0] * (len(conflictingPairs) + 1)
        t1, t1id, t2 = 0, -1, 0
        base = 0
        for r in range(1, n + 1):
            for a, idx in pairs_by_b[r]:
                if a > t1:
                    t2 = t1
                    t1, t1id = a, idx
                elif a > t2:
                    t2 = a
            if t1 > 0:
                gain[t1id] += t1 - t2
            base += r - t1
        return base + max(gain)

