        cnt = [0]*(L+2)
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = L-1-i
                # set this bit to 0, rest free: need c-ones ones among rem bits
                for t in range(0, rem+1):
                    cnt[ones+t] = (cnt[ones+t] + C[rem][t]) % MOD
                ones += 1
        # steps
        def pc(x):
            return bin(x).count('1')
        steps = [0]*(L+2)
        steps[1] = 0
        for c in range(2, L+2):
            steps[c] = 1 + steps[pc(c)]
        ans = 0
        for c in range(1, L+2):
            if steps[c] <= k-1:
                ans += cnt[c]
        return ans % MOD

