from functools import lru_cache
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        @lru_cache(maxsize=None)
        def f(o, e, p):
            if o < 0 or e < 0:
                return 0
            if o == 0 and e == 0:
                return 1
            if p == 1:
                return e * f(o, e - 1, 0)
            return o * f(o - 1, e, 1)

        rem = list(range(1, n + 1))
        total = 0
        for v in rem:
            o = sum(1 for x in rem if x % 2 == 1) - (v % 2)
            e = sum(1 for x in rem if x % 2 == 0) - (1 - v % 2)
            total += f(o, e, v % 2)
        if k > total:
            return []
        res = []
        last = None
        for _ in range(n):
            no = sum(1 for x in rem if x % 2 == 1)
            ne = len(rem) - no
            chosen = None
            for v in rem:
                if last is not None and v % 2 == last:
                    continue
                o = no - (v % 2)
                e = ne - (1 - v % 2)
                c = f(o, e, v % 2)
                if k <= c:
                    chosen = v
                    break
                k -= c
            res.append(chosen)
            rem.remove(chosen)
            last = chosen % 2
        return res

