class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        full = (1 << k) - 1
        p = [pow(10, i, k) for i in range(n)]
        w = []
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w.append(p[i] % k)
            else:
                w.append((p[i] + p[j]) % k)
        S = [0] * (h + 1)
        S[h] = 1
        for i in range(h - 1, -1, -1):
            m = S[i + 1]
            res = 0
            seen = set()
            for d in range(10):
                c = (w[i] * d) % k
                if c in seen:
                    continue
                seen.add(c)
                if c == 0:
                    res |= m
                else:
                    res |= ((m << c) | (m >> (k - c))) & full
            S[i] = res
        digits = []
        r = 0
        for i in range(h):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                nr = (r + w[i] * d) % k
                t = (-nr) % k
                if (S[i + 1] >> t) & 1:
                    digits.append(d)
                    r = nr
                    break
            else:
                return ""
        left = digits
        if n % 2 == 0:
            s = left + left[::-1]
        else:
            s = left + left[:-1][::-1]
        return "".join(map(str, s))

