from typing import List
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        a = nums
        n = len(a)
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + a[i]
        nxt = [n] * n
        st = []
        for i in range(n):
            while st and a[st[-1]] < a[i]:
                nxt[st.pop()] = i
            st.append(i)
        W = [0] * (n + 1)
        for j in range(n - 1, -1, -1):
            W[j] = a[j] * (nxt[j] - j) + W[nxt[j]]
        sp = [list(range(n))]
        j = 1
        while (1 << j) <= n:
            prev = sp[-1]
            h = 1 << (j - 1)
            cur = []
            for i in range(n - (1 << j) + 1):
                x = prev[i]; y = prev[i + h]
                cur.append(x if a[x] >= a[y] else y)
            sp.append(cur)
            j += 1

        def qmax(l, r):
            t = (r - l + 1).bit_length() - 1
            x = sp[t][l]; y = sp[t][r - (1 << t) + 1]
            return x if a[x] >= a[y] else y

        def cost(l, r):
            jj = qmax(l, r)
            return W[l] - W[jj] + a[jj] * (r + 1 - jj) - (P[r + 1] - P[l])

        ans = 0
        r = 0
        for l in range(n):
            if r < l:
                r = l
            while r + 1 < n and cost(l, r + 1) <= k:
                r += 1
            ans += r - l + 1
        return ans

