import sys, heapq
def prefix_T(seq):
    lo = []; hi = []; loSum = 0; total = 0
    T = [0]*(len(seq)+1)
    hp = heapq.heappush; hpop = heapq.heappop
    for L in range(1, len(seq)+1):
        x = seq[L-1]
        total += x
        if lo and x < -lo[0]:
            hp(lo, -x); loSum += x
        else:
            hp(hi, x)
        t = L//2
        while len(lo) > t:
            y = -hpop(lo); loSum -= y; hp(hi, y)
        while len(lo) < t:
            y = hpop(hi); loSum += y; hp(lo, -y)
        if L % 2 == 0:
            T[L] = total - 2*loSum
    return T
def solve(n, A):
    if n == 1:
        return 0
    Tpre = prefix_T(A)
    if n % 2 == 0:
        return Tpre[n]
    Tsuf = prefix_T(A[::-1])
    best = 0
    for L in range(0, n, 2):
        best = max(best, Tpre[L] + Tsuf[n-1-L])
    return best
