import bisect

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def occ(t):
            if not t:
                return list(range(n + 1))
            comb = t + '\x00' + s
            L = len(comb)
            pi = [0] * L
            k = 0
            for i in range(1, L):
                while k and comb[i] != comb[k]:
                    k = pi[k - 1]
                if comb[i] == comb[k]:
                    k += 1
                pi[i] = k
            m = len(t)
            res = []
            for i in range(m + 1, L):
                if pi[i] == m:
                    res.append(i - 2 * m)
            return res

        A, B, C = occ(a), occ(b), occ(c)
        if not A or not B or not C:
            return -1
        best = -1
        la, lb, lc = len(a), len(b), len(c)
        for i in A:
            x = bisect.bisect_left(B, i + la)
            if x == len(B):
                continue
            kb = B[x]
            y = bisect.bisect_left(C, kb + lb)
            if y == len(C):
                continue
            cand = C[y] + lc - i
            if best < 0 or cand < best:
                best = cand
        return best

