    data=sys.stdin.buffer.read().split()
    n=int(data[0]); m=int(data[1])
    parent=list(range(n+1)); pot=[0]*(n+1); size=[1]*(n+1)
    def find(x):
        path=[]
        while parent[x]!=x:
            path.append(x); x=parent[x]
        root=x
        for u in reversed(path):
            pot[u]^=pot[parent[u]]
            parent[u]=root
        return root
    idx=2
    for _ in range(m):
        x=int(data[idx]); y=int(data[idx+1]); z=int(data[idx+2]); idx+=3
        rx=find(x); px=pot[x] if x!=rx else 0
        ry=find(y); py=pot[y] if y!=ry else 0
        if rx==ry:
            if px^py!=z:
                print(-1); return
        else:
            if size[rx]>size[ry]:
                rx,ry=ry,rx; px,py=py,px
            parent[rx]=ry
            pot[rx]=px^py^z
            size[ry]+=size[rx]
    roots=[0]*(n+1)
    p=[0]*(n+1)
    for v in range(1,n+1):
        r=find(v)
        roots[v]=r
        p[v]=pot[v] if v!=r else 0
    C=[0]*(n+1)
    cnt=[0]*(n+1)
    for b in range(31):
        for i in range(n+1):
            cnt[i]=0
        for v in range(1,n+1):
            if (p[v]>>b)&1:
                cnt[roots[v]]+=1
        for r in range(1,n+1):
            if parent[r]==r:
                s=size[r]; c=cnt[r]
                if s-c<c:
                    C[r]|=(1<<b)
    out=[]
    for v in range(1,n+1):
        out.append(p[v]^C[roots[v]])
    print(' '.join(map(str,out)))
