import sys, time
from math import comb
from itertools import combinations, chain
import numpy as np

def solve(N, K, vals):
    if K == 0:
        return 0
    m = min(K, N - K)
    arr = np.array(vals, dtype=np.int64)
    total = 0
    for v in vals:
        total ^= v
    if m == 0:
        return total
    C = comb(N, m)
    idx = np.fromiter(chain.from_iterable(combinations(range(N), m)),
                      dtype=np.int32, count=C * m).reshape(C, m)
    S = np.bitwise_xor.reduce(arr[idx], axis=1)
    if K <= N - K:
        return int(S.max())
    return int((S ^ np.int64(total)).max())

def main():
    data = sys.stdin.read().split()
    N, K = int(data[0]), int(data[1])
    vals = [int(x) for x in data[2:2+N]]
    print(solve(N, K, vals))

