class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        for _ in range(t):
            z = cnt[25]
            new = [0] * 26
            new[0] = z
            new[1] = (cnt[0] + z) % MOD
            for i in range(2, 26):
                new[i] = cnt[i - 1]
            cnt = [x % MOD for x in new]
        return sum(cnt) % MOD

