import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        L = len(str(n))
        lim = 10 ** L
        sv = [True] * (lim + 1)
        sv[0] = sv[1] = False
        for i in range(2, int(lim ** 0.5) + 1):
            if sv[i]:
                for j in range(i * i, lim + 1, i):
                    sv[j] = False
        if sv[n] or sv[m]:
            return -1
        if n == m:
            return n
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, v = heapq.heappop(pq)
            if d != dist.get(v):
                continue
            if v == m:
                return d
            for i in range(L):
                p = 10 ** i
                dg = (v // p) % 10
                for delta in (1, -1):
                    if dg + delta < 0 or dg + delta > 9:
                        continue
                    u = v + delta * p
                    if sv[u]:
                        continue
                    nd = d + u
                    if nd < dist.get(u, 1 << 60):
                        dist[u] = nd
                        heapq.heappush(pq, (nd, u))
        return -1

