import numpy as np
class Solution:
    def beautifulSplits(self, nums):
        n = len(nums)
        if n < 3:
            return 0
        a = np.array(nums, dtype=np.int64)
        z = [0]*n; z[0] = n; l = r = 0
        for i in range(1, n):
            if i < r:
                z[i] = min(r-i, z[i-l])
            while i+z[i] < n and nums[z[i]] == nums[i+z[i]]:
                z[i] += 1
            if i+z[i] > r:
                l = i; r = i+z[i]
        nxt = np.zeros(n+1, dtype=np.int64)
        total = 0
        for i in range(n-1, 0, -1):
            cur = np.zeros(n+1, dtype=np.int64)
            cur[:n] = np.where(a == a[i], nxt[1:]+1, 0)
            nxt = cur
            if i <= n-2:
                js = np.arange(i+1, n, dtype=np.int64)
                B = (cur[i+1:n] >= js-i) & (2*js-i <= n)
                if z[i] >= i:
                    A = js >= 2*i
                else:
                    A = np.zeros(len(js), dtype=bool)
                total += int(A.sum()) + int(B.sum()) - int((A & B).sum())
        return total

