        pts = [tuple(p) for p in points]
        S = set(pts)
        n = len(pts)
        best = -1
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                x1, y1 = pts[i]
                x2, y2 = pts[j]
                if x1 < x2 and y1 < y2:
                    c1 = (x1, y2)
                    c2 = (x2, y1)
                    if c1 in S and c2 in S:
                        ok = True
                        for (px, py) in pts:
                            if (px, py) in ((x1, y1), (x2, y2), c1, c2):
                                continue
                            if x1 <= px <= x2 and y1 <= py <= y2:
                                ok = False
                                break
                        if ok:
                            best = max(best, (x2 - x1) * (y2 - y1))
        return best

